739: /* for each key we scan in the main dict, this function will attempt to defrag
740:  * all the various pointers it has. */
741: void defragKey(defragCtx *ctx, dictEntry *de) {
742:     sds keysds = dictGetKey(de);
743:     robj *newob, *ob = dictGetVal(de);
744:     unsigned char *newzl;
745:     sds newsds;
746:     redisDb *db = ctx->privdata;
747:     int slot = ctx->slot;
748:     /* Try to defrag the key name. */
749:     newsds = activeDefragSds(keysds);
750:     if (newsds) {
751:         kvstoreDictSetKey(db->keys, slot, de, newsds);
752:         if (kvstoreDictSize(db->expires, slot)) {
753:             /* We can't search in db->expires for that key after we've released
754:              * the pointer it holds, since it won't be able to do the string
755:              * compare, but we can find the entry using key hash and pointer. */
756:             uint64_t hash = kvstoreGetHash(db->expires, newsds);
757:             dictEntry *expire_de = kvstoreDictFindByHashAndPtr(db->expires, slot, keysds, hash);
758:             if (expire_de) kvstoreDictSetKey(db->expires, slot, expire_de, newsds);
759:         }
760: 
761:         /* Update the key's reference in the dict's metadata or the listpackEx. */
762:         if (unlikely(ob->type == OBJ_HASH))
763:             hashTypeUpdateKeyRef(ob, newsds);
764:     }
765: 
766:     /* Try to defrag robj and / or string value. */
767:     if (unlikely(ob->type == OBJ_HASH && hashTypeGetMinExpire(ob, 0) != EB_EXPIRE_TIME_INVALID)) {
768:         /* Update its reference in the ebucket while defragging it. */
769:         newob = ebDefragItem(&db->hexpires, &hashExpireBucketsType, ob,
770:                              (ebDefragFunction *)activeDefragStringOb);
771:     } else {
772:         /* If the dict doesn't have metadata, we directly defrag it. */
773:         newob = activeDefragStringOb(ob);
774:     }
775:     if (newob) {
776:         kvstoreDictSetVal(db->keys, slot, de, newob);
777:         ob = newob;
778:     }
779: 
780:     if (ob->type == OBJ_STRING) {
781:         /* Already handled in activeDefragStringOb. */
782:     } else if (ob->type == OBJ_LIST) {
783:         if (ob->encoding == OBJ_ENCODING_QUICKLIST) {
784:             defragQuicklist(db, de);
785:         } else if (ob->encoding == OBJ_ENCODING_LISTPACK) {
786:             if ((newzl = activeDefragAlloc(ob->ptr)))
787:                 ob->ptr = newzl;
788:         } else {
789:             serverPanic("Unknown list encoding");
790:         }
791:     } else if (ob->type == OBJ_SET) {
792:         if (ob->encoding == OBJ_ENCODING_HT) {
793:             defragSet(db, de);
794:         } else if (ob->encoding == OBJ_ENCODING_INTSET ||
795:                    ob->encoding == OBJ_ENCODING_LISTPACK)
796:         {
797:             void *newptr, *ptr = ob->ptr;
798:             if ((newptr = activeDefragAlloc(ptr)))
799:                 ob->ptr = newptr;
800:         } else {
801:             serverPanic("Unknown set encoding");
802:         }
803:     } else if (ob->type == OBJ_ZSET) {
804:         if (ob->encoding == OBJ_ENCODING_LISTPACK) {
805:             if ((newzl = activeDefragAlloc(ob->ptr)))
806:                 ob->ptr = newzl;
807:         } else if (ob->encoding == OBJ_ENCODING_SKIPLIST) {
808:             defragZsetSkiplist(db, de);
809:         } else {
810:             serverPanic("Unknown sorted set encoding");
811:         }
812:     } else if (ob->type == OBJ_HASH) {
813:         if (ob->encoding == OBJ_ENCODING_LISTPACK) {
814:             if ((newzl = activeDefragAlloc(ob->ptr)))
815:                 ob->ptr = newzl;
816:         } else if (ob->encoding == OBJ_ENCODING_LISTPACK_EX) {
817:             listpackEx *newlpt, *lpt = (listpackEx*)ob->ptr;
818:             if ((newlpt = activeDefragAlloc(lpt)))
819:                 ob->ptr = lpt = newlpt;
820:             if ((newzl = activeDefragAlloc(lpt->lp)))
821:                 lpt->lp = newzl;
822:         } else if (ob->encoding == OBJ_ENCODING_HT) {
