214: /* Defrag helper for sorted set.
215:  * Update the robj pointer, defrag the skiplist struct and return the new score
216:  * reference. We may not access oldele pointer (not even the pointer stored in
217:  * the skiplist), as it was already freed. Newele may be null, in which case we
218:  * only need to defrag the skiplist, but not update the obj pointer.
219:  * When return value is non-NULL, it is the score reference that must be updated
220:  * in the dict record. */
221: double *zslDefrag(zskiplist *zsl, double score, sds oldele, sds newele) {
222:     zskiplistNode *update[ZSKIPLIST_MAXLEVEL], *x, *newx;
223:     int i;
224:     sds ele = newele? newele: oldele;
225: 
226:     /* find the skiplist node referring to the object that was moved,
227:      * and all pointers that need to be updated if we'll end up moving the skiplist node. */
228:     x = zsl->header;
229:     for (i = zsl->level-1; i >= 0; i--) {
230:         while (x->level[i].forward &&
231:             x->level[i].forward->ele != oldele && /* make sure not to access the
232:                                                      ->obj pointer if it matches
233:                                                      oldele */
234:             (x->level[i].forward->score < score ||
235:                 (x->level[i].forward->score == score &&
236:                 sdscmp(x->level[i].forward->ele,ele) < 0)))
237:             x = x->level[i].forward;
238:         update[i] = x;
239:     }
240: 
241:     /* update the robj pointer inside the skip list record. */
242:     x = x->level[0].forward;
243:     serverAssert(x && score == x->score && x->ele==oldele);
244:     if (newele)
245:         x->ele = newele;
246: 
247:     /* try to defrag the skiplist record itself */
248:     newx = activeDefragAlloc(x);
249:     if (newx) {
250:         zslUpdateNode(zsl, x, newx, update);
251:         return &newx->score;
252:     }
253:     return NULL;
254: }
