404: long scanLaterList(robj *ob, unsigned long *cursor, long long endtime) {
405:     quicklist *ql = ob->ptr;
406:     quicklistNode *node;
407:     long iterations = 0;
408:     int bookmark_failed = 0;
409:     if (ob->type != OBJ_LIST || ob->encoding != OBJ_ENCODING_QUICKLIST)
410:         return 0;
411: 
412:     if (*cursor == 0) {
413:         /* if cursor is 0, we start new iteration */
414:         node = ql->head;
415:     } else {
416:         node = quicklistBookmarkFind(ql, "_AD");
417:         if (!node) {
